import type { IconName } from '../lib/types.ts'
import { cn } from '../lib/text.ts'

export function Icon({ name, className }: { name: IconName; className?: string }) {
  return (
    <svg className={cn('i', className)} aria-hidden="true">
      <use href={`#i-${name}`} />
    </svg>
  )
}

